files={"tools/pistol_portrait_20260914/portrait_anatomy.py":"\"\"\"Portrait-only correction; normal animation generation is unchanged.\"\"\"\nfrom contextlib import contextmanager\nimport inspect\nimport build, outfits\n_ORIGINAL = build.make\n_SOURCE = inspect.getsource(_ORIGINAL)\n_OLD = \"sleeve_start=support_elbow*.55+support_end*.45\"\nassert _SOURCE.count(_OLD) == 1\n_SOURCE = _SOURCE.replace(_OLD, \"sleeve_start=support_elbow\")\n_SOURCE = _SOURCE.replace(\"if costume:outfits.forearm(up,sleeve_start,support_end,costume,skin,hi,2.8)\",\n \"if costume:outfits.forearm(up,sleeve_start,support_end,costume,skin,hi,3.1)\")\n_NAMESPACE = dict(build.__dict__)\nexec(compile(_SOURCE, __file__, 'exec'), _NAMESPACE)\n_CORRECTED = _NAMESPACE['make']\n\n@contextmanager\ndef corrected(legacy_shoulders=False):\n    old_make, old_arm = build.make, outfits.arm\n    if legacy_shoulders:\n        import eastex_outfits\n        def joined(parent,a,b,h,c,skin,hi):\n            # Reuse the accepted connected sleeve with the same joints/radii.\n            costume=dict(c,new_unit=True,eastex=True)\n            return eastex_outfits.arm(parent,a,b,h,costume,skin,hi)\n        outfits.arm=joined\n    build.make=_CORRECTED\n    try: yield\n    finally: build.make,outfits.arm=old_make,old_arm\n","tools/pistol_portrait_20260914/worker.py":"from pathlib import Path\nimport sys, json, importlib, copy, xml.etree.ElementTree as E\nimport numpy as np\nR=Path(__file__).resolve().parents[2]\nO=Path(__file__).parent\nsys.path[:0]=[str(R/'tools/faction_roster'),str(R/'tools/faction_design'),str(R/'tools/arsenal_production'),str(R/'tools/unit_source_recovery'),str(R/'tools/unit_source_recovery/src')]\nimport build_art as art, showcase_build as show, showcase_finish as finish\nprofile=sys.argv[1]\nstyle=None if profile in ['mercer','orlov'] else importlib.import_module(profile+'_outfits')\nimport mercer_preview as rig\nimport portrait_anatomy as repair\nrows=[x for x in json.loads((O/'inventory.json').read_text()) if x['faction']==profile]\nif '--sample' in sys.argv: rows=[x for x in rows if x['model']=='glock_17']\nmodels={m['id']:m for m in art.MODELS}\nextra=[] if style is None else [v[1:] for c in style.SPECS.values() for v in c.values() if isinstance(v,str) and v.startswith('#')]\nextra+=['244d92','3d6bb3','19335d','929c9b','786244','202923','303d28','7f7956','30302a']\nif style is not None:extra += [v.lstrip('#') for v in getattr(style,'EXTRA_PALETTE',[])]\npalette=np.vstack([finish.PAL,np.array([tuple(bytes.fromhex(v)) for v in extra],dtype=np.int32)])\njobs=[];report=[]\nfor row in rows:\n    model=models[row['model']]\n    for direction in ['SE','SW']:\n        def make():\n            st=show.state('idle',0,'pistol')\n            if style is not None:\n                root=style.make('pistol',model,direction,**st)\n                wrap=E.Element(art.N+'g',{'transform':'translate(0 -6)'})\n                for child in list(root):root.remove(child);wrap.append(child)\n                root.append(wrap)\n                return root\n            art.bind(model)\n            return art.directions.make(0 if profile=='mercer' else 1,st.pop('q'),direction,'pistol',**st)\n        original=make()\n        with repair.corrected(style is None): candidate=make()\n        assert rig.body_signature(original)==rig.body_signature(candidate)\n        assert rig.lower_signature(original)==rig.lower_signature(candidate)\n        for name,root in [('before',original),('after',candidate)]:\n            label=row['variant']+'_'+direction+'_'+name\n            jobs.append([label,E.tostring(root,encoding='unicode')])\n        report.append({'variant':row['variant'],'direction':direction,'body_unchanged':True,'lower_unchanged':True})\n(O/'jobs').mkdir(exist_ok=True)\n(O/'jobs'/(profile+'.json')).write_text(json.dumps({'jobs':jobs,'palette':palette.tolist(),'report':report,'rows':rows}),encoding='utf-8')\nprint('PORTRAIT_SVG',profile,len(jobs),flush=True)\n","tools/pistol_portrait_20260914/render.gd":"extends SceneTree\nfunc _initialize():\n var args=OS.get_cmdline_user_args()\n var data=JSON.parse_string(FileAccess.get_file_as_string(args[0]))\n for job in data.jobs:\n  var im=Image.new()\n  if im.load_svg_from_string(job[1],2.0)!=OK:quit(1);return\n  im.resize(128,128,Image.INTERPOLATE_LANCZOS)\n  if im.save_png(args[1]+\"/\"+job[0]+\".png\")!=OK:quit(2);return\n print(\"PORTRAIT_RENDERED \",data.jobs.size())\n quit()\n","tools/pistol_portrait_20260914/sample.py":"from pathlib import Path\nimport subprocess,sys,json\nfrom PIL import Image,ImageDraw,ImageFont\nimport numpy as np\nR=Path(__file__).resolve().parents[2];O=Path(__file__).parent\nsys.path.insert(0,str(R/'tools/faction_roster'))\nfrom build_roster import finish_exact\nprofiles=['mercer','orlov','calle_ocho','trc','whittaker','ventresca']\n(O/'renders').mkdir(exist_ok=True)\nfor profile in profiles:\n subprocess.run([sys.executable,str(O/'worker.py'),profile,'--sample'],cwd=R,check=True)\n job=O/'jobs'/(profile+'.json')\n p=subprocess.run([r'C:\\Users\\brand\\OneDrive\\Documents\\Godot\\Godot_v4.7.2-stable_win64_console.exe','--headless','--path',str(R),'--script',str(O/'render.gd'),'--',str(job),str(O/'renders')],capture_output=True,text=True)\n assert p.returncode==0,p.stdout+p.stderr\n data=json.loads(job.read_text())\n for name,svg in data['jobs']:finish_exact(O/'renders'/(name+'.png'),np.array(data['palette'],dtype=np.int32))\nim=Image.new('RGB',(1280,1320),'#263033');draw=ImageDraw.Draw(im);font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',18)\nfor i,profile in enumerate(profiles):\n data=json.loads((O/'jobs'/(profile+'.json')).read_text());v=data['rows'][0]['variant'];y=i*220\n draw.text((10,y+6),profile+'       SW before / after                           SE before / after',font=font,fill='#e9e3d6')\n for col,(direction,state) in enumerate([('SW','before'),('SW','after'),('SE','before'),('SE','after')]):\n  actor=Image.open(O/'renders'/(v+'_'+direction+'_'+state+'.png')).convert('RGBA').crop((18,6,108,86)).resize((270,240),Image.Resampling.NEAREST)\n  im.paste(actor,(col*320,y+12),actor)\nim.save(O/'candidate_sample.png')\nprint('CANDIDATE_REVIEW_READY',flush=True)\n"}
